using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Study of literature, writing, and rhetoric." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and their significance." }
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor of Computer Science", Bio = "Dr. Chen has over 15 years of experience in distributed systems and cloud computing. She received her PhD from MIT and has published over 50 papers in top-tier venues.", Email = "achen@university.edu" },
            new() { Id = 2, Name = "Dr. Robert Martinez", Title = "Associate Professor of Mathematics", Bio = "Dr. Martinez specializes in applied mathematics and numerical analysis. He is the author of two widely-used textbooks on linear algebra.", Email = "rmartinez@university.edu" },
            new() { Id = 3, Name = "Prof. Sarah Williams", Title = "Professor of English", Bio = "Prof. Williams is an award-winning author and literary critic with expertise in 20th-century American literature.", Email = "swilliams@university.edu" },
            new() { Id = 4, Name = "Dr. James Park", Title = "Assistant Professor of Physics", Bio = "Dr. Park conducts research in quantum mechanics and particle physics. He previously worked at CERN.", Email = "jpark@university.edu" },
            new() { Id = 5, Name = "Dr. Maria Garcia", Title = "Professor of History", Bio = "Dr. Garcia is a leading scholar in Latin American history and has received multiple grants for her archival research.", Email = "mgarcia@university.edu" },
            new() { Id = 6, Name = "Dr. Kevin Liu", Title = "Associate Professor of Computer Science", Bio = "Dr. Liu focuses on artificial intelligence and machine learning, with recent work in natural language processing.", Email = "kliu@university.edu" }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "An introductory course covering programming fundamentals using Python. Topics include variables, control structures, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, DepartmentName = "Computer Science", InstructorId = 1, IsFeatured = true },
            new() { Id = 2, Code = "CS 301", Title = "Data Structures and Algorithms", Description = "Advanced study of data structures (trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming, greedy algorithms). Includes complexity analysis.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", DepartmentId = 1, DepartmentName = "Computer Science", InstructorId = 1, IsFeatured = false },
            new() { Id = 3, Code = "CS 410", Title = "Machine Learning", Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, and model evaluation. Students complete a semester-long project.", Credits = 4, Schedule = "Tue/Thu 2:00–3:20 PM", DepartmentId = 1, DepartmentName = "Computer Science", InstructorId = 6, IsFeatured = true },
            new() { Id = 4, Code = "MATH 201", Title = "Linear Algebra", Description = "Study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and eigenvectors with applications to science and engineering.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = 2, DepartmentName = "Mathematics", InstructorId = 2, IsFeatured = false },
            new() { Id = 5, Code = "MATH 301", Title = "Differential Equations", Description = "Ordinary differential equations, Laplace transforms, series solutions, and systems of equations with applications in physics and engineering.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = 2, DepartmentName = "Mathematics", InstructorId = 2, IsFeatured = true },
            new() { Id = 6, Code = "ENG 102", Title = "Academic Writing", Description = "Development of academic writing skills including research, argumentation, and citation. Students produce a portfolio of essays.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", DepartmentId = 3, DepartmentName = "English", InstructorId = 3, IsFeatured = false },
            new() { Id = 7, Code = "ENG 350", Title = "American Literature", Description = "Survey of major American literary works from the colonial period to the present, examining cultural and historical contexts.", Credits = 3, Schedule = "Mon/Wed 1:00–2:20 PM", DepartmentId = 3, DepartmentName = "English", InstructorId = 3, IsFeatured = false },
            new() { Id = 8, Code = "PHYS 201", Title = "Classical Mechanics", Description = "Newtonian mechanics, conservation laws, oscillations, gravitation, and introduction to Lagrangian mechanics.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", DepartmentId = 4, DepartmentName = "Physics", InstructorId = 4, IsFeatured = true },
            new() { Id = 9, Code = "PHYS 401", Title = "Quantum Mechanics", Description = "Introduction to quantum theory: wave functions, Schrödinger equation, hydrogen atom, spin, and quantum entanglement.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:20 PM", DepartmentId = 4, DepartmentName = "Physics", InstructorId = 4, IsFeatured = false },
            new() { Id = 10, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of world civilizations from prehistory to 1500 CE, covering major political, social, and cultural developments.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", DepartmentId = 5, DepartmentName = "History", InstructorId = 5, IsFeatured = false },
            new() { Id = 11, Code = "HIST 310", Title = "Modern Latin America", Description = "Political, economic, and cultural history of Latin America from independence movements to the present day.", Credits = 3, Schedule = "Mon/Wed 3:00–4:20 PM", DepartmentId = 5, DepartmentName = "History", InstructorId = 5, IsFeatured = true }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public Instructor? GetInstructor(int id) => _instructors.FirstOrDefault(i => i.Id == id);
}

